body:
{
  "options": [
    {
      "id": "A",
      "summary": "重生千金步步为营，4章完成从复仇到商界颠覆的爽感闭环",
      "chapters": [
        {
          "num": 1,
          "role": "hook_open",
          "title": "重生，报警抓人",
          "core_event": "女主林薇重生回被害前一小时，直接报警举报渣男闺蜜林峰挪用公款和谋杀未遂，林峰被警察带走，女主接管公司紧急事务。",
          "emotion": "愤怒、爽快、悬念",
          "hook": "林峰被抓前冷笑：‘你以为胜了？你爸的烂摊子马上就爆。’",
          "beat": "【场景目的】建立重生+背叛+第一波反击\n【核心动作】林薇回忆前世死亡场景（50字）→ 看时钟发现回到过去 → 报警 → 与林峰对峙 → 警察带走人\n【节奏档位】快（前200字冲突，500字内反转）\n【结尾钩子】电话响起：公司副总裁急报有一笔3亿对赌即将到期。",
          "intent": {
            "ai_suggest": "重生梗+报警抓人+反差爽感+代入女主愤怒情绪"
          }
        },
        {
          "num": 2,
          "role": "buildup",
          "title": "商界第一刀",
          "core_event": "林薇利用前世记忆，抢先与林峰的秘密合作伙伴谈判，截断其资金链，并拿到对方挪用公款的证据，迫使对赌条款延期。",
          "emotion": "紧张、步步为营、颅内高潮",
          "hook": "刚稳住公司，私家侦探发来照片——林峰取保候审，并与神秘人密会，照片上的人正是前世害死她父亲的幕后推手。",
          "beat": "【场景目的】展现女主智商，铺垫更大反派\n【核心动作】林薇查看前世重要时间节点（1句话）→ 约见合作方张总 → 用谈判技巧和证据逼迫对方让步 → 签署延期协议\n【节奏档位】中（对话为主，穿插心理活动）\n【结尾钩子】照片特写：神秘人侧脸，林薇认出一这是前世父亲死前见过的最后一个人。",
          "intent": {
            "ai_suggest": "高智商谈判+信息差碾压+商战爽感"
          }
        },
        {
          "num": 3,
          "role": "paywall",
          "title": "棋局翻盘",
          "core_event": "林薇设计让神秘人赵董露出马脚，在董事会上当众播放录音，联合小股东夺回公司控制权。赵董被反噬，林峰再度被捕且不得保释。",
          "emotion": "高潮、彻底翻盘、爽点峰值",
          "hook": "赵董被带走前低语：‘你妈还活着，你想知道她在哪吗？’",
          "beat": "【场景目的】付费节点——本卷最大危机反转\n【核心动作】林薇设宴请赵董入局 → 伪装让步诱导其说出计划 → 录音 → 董事会摊牌 → 警方介入\n【节奏档位】快（紧张对峙+多轮反转）\n【结尾钩子】赵董被抓后，黑暗中出现一个戴面具的女人，轻声说：‘小薇，终于长大了。’",
          "intent": {
            "ai_suggest": "读者付费心理状态：看到女主从被动到主动，但更大的谜团留给付费篇"
          }
        },
        {
          "num": 4,
          "role": "finale",
          "title": "母亲的秘密",
          "core_event": "林薇根据线索找到被囚禁多年的母亲，母女联手揭开赵董幕后更大的犯罪集团，同时林峰的案子终审判决。林薇将公司交给可靠团队，陪母亲疗伤，暗示新的战役即将开始。",
          "emotion": "感动、释然、开放式期待",
          "hook": "林薇和母亲走在海边，母亲突然说：‘其实你重生那天，我也重生了。’",
          "beat": "【场景目的】收尾主线，开放新线索提高追读\n【核心动作】林薇循线索找到城郊旧宅 → 解救母亲 → 母女相认 → 林峰被判无期 → 公司稳固 → 结尾对话\n【节奏档位】中慢（情感释放+留白）\n【结尾钩子】最后一句话：海风吹过，母亲微笑着握住她的手，眼底闪过一道林薇熟悉的冷光。",
          "intent": {
            "ai_suggest": {
              "core_task": {
                "opening_gap": "母亲存活是女主前世完全不知的信息",
                "freeze_frame": "母女在海边对话，温暖但暗藏惊雷",
                "open_ending": "母亲说自己也重生，暗示母亲可能有自己的复仇线，为第二季埋伏笔"
              }
            }
          }
        }
      ]
    }
  ]
}

{
  "options": [
    {
      "id": "A",
      "summary": "重生复仇高智商博弈，4章紧凑结构：第1章重生反杀报警，第2章付费点商界布局遇阻，第3章解悬念施计，第4章终极对决揭开真相。",
      "chapters": [
        {
          "num": 1,
          "title": "重生，报警抓人",
          "role": "hook_open",
          "core_event": "女主重生死前一刻，冷静录音渣男与闺蜜密谋害命证据，暗中报警，将两人当场抓获。",
          "emotion": "紧张→极致爽快",
          "hook": "渣男被押时诡秘一笑，暗示背后另有主谋。",
          "beat": "【场景目的】展示重生复仇原点，立女主冷静果断人设\n【核心动作】录音取证→报警→对峙\n【节奏档位】快\n【结尾钩子】渣男的笑背后隐藏什么？",
          "intent": {
            "ai_suggest": "重生反转梗+报警打脸+紧张解密+代入女主"
          }
        },
        {
          "num": 2,
          "title": "第一步棋，拿下董事会",
          "role": "paywall",
          "core_event": "女主利用前世记忆，提前揭露公司内鬼，争夺董事会控制权，却遭到神秘力量阻挠。",
          "emotion": "智斗紧张→期待",
          "hook": "投票前最后一刻，女主手机收到匿名威胁：“你以为你赢了？”",
          "beat": "【场景目的】建立商界博弈主线，设置付费悬念\n【核心动作】揭露叛徒→争取股东→遭威胁\n【节奏档位】中\n【结尾钩子】匿名威胁来自谁？女主如何破局？",
          "intent": {
            "ai_suggest": "读者付费前的心理状态：主角能否逆袭？神秘势力的身份？后续如何颠覆整个棋局？"
          }
        },
        {
          "num": 3,
          "title": "暗棋落定，谁在局中",
          "role": "paid_open",
          "core_event": "女主查出威胁短信来源，将计就计设反间计，引蛇出洞，成功挫败对方第一步攻势。",
          "emotion": "烧脑爽快→更深的悬念",
          "hook": "计谋得逞，但闺蜜家族背后竟隐现更大的利益集团。",
          "beat": "【场景目的】解付费悬念并升级冲突\n【核心动作】调查来源→设反间计→引蛇出洞\n【节奏档位】快\n【结尾钩子】大鱼未现，女主决定主动出击。"
        },
        {
          "num": 4,
          "title": "终局，大仇得报",
          "role": "finale",
          "core_event": "女主联合警方与原公司忠臣，一举揭露幕后黑手（政商勾结链），致其破产入狱，重掌家族产业。",
          "emotion": "圆满解气→余韵",
          "hook": "一切落幕，女主收到陌生消息：“游戏才刚刚开始。”",
          "beat": "【场景目的】完成复仇主线，回收所有伏笔，留续集可能\n【核心动作】联合警方→终极对峙→大获全胜\n【节奏档位】中\n【结尾钩子】开放式结局，新危机初显。",
          "intent": {
            "ai_suggest": {
              "core_task": {
                "opening_gap": "从被闺蜜和渣男害死到掌控商界、真相大白",
                "freeze_frame": "女主站在新公司天台，微笑展望未来",
                "open_ending": "手机神秘消息暗示更大棋局"
              }
            }
          }
        }
      ]
    }
  ]
}
